import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Normalização de eventos, lotes e lacunas","description":"","frontmatter":{"title":"Normalização de eventos, lotes e lacunas","docId":"developer.events","translationKey":"developer.events","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2e7b95a47d3549b3703af620f2f167fdccd8c2d207c513f1b99f3da334e37980","translationRevision":"0dec28ef4c14b70c8ecc4e0b50389e18b71b33fba4f371854f0b23e4b8aed255","order":100},"headers":[],"relativePath":"pt/developer/events.md","filePath":"pt/developer/events.md","lastUpdated":1795731074000}`),a={name:`pt/developer/events.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="event-normalization-batches-and-gaps" tabindex="-1">Normalização de eventos, lotes e lacunas <a class="header-anchor" href="#event-normalization-batches-and-gaps" aria-label="Permalink to “Normalização de eventos, lotes e lacunas”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Consuma eventos de LIVE sem contagem duplicada nem confundir recuperação de apresentação com execução. Entenda a <a href="./storage.html">persistência</a> e use dados de teste sanitizados em vez de capturas de contas reais. <code>tiktools-tiktok</code> envolve as dependências fixadas de assinatura/decodificação e exporta valores estáveis do TikTools; o núcleo não expõe objetos protobuf como API do aplicativo.</p><h2 id="follow-the-implemented-pipeline" tabindex="-1">Siga o pipeline implementado <a class="header-anchor" href="#follow-the-implemented-pipeline" aria-label="Permalink to “Siga o pipeline implementado”">​</a></h2><p>A entrada captura o contexto original de conexão de criador/sala antes do trabalho assíncrono. A normalização produz valores de chat, presentes, curtidas, atividade social e ciclo de vida. O núcleo publica originais e gerencia o trabalho de contabilização/efeitos separadamente. Processadores podem associar evidências derivadas limitadas em <code>event.intel</code>; falhas preservam eventos brutos com diagnósticos de degradação. Contratos gerados de automação descrevem apenas campos emitidos.</p><p>A identidade de repetição do backend inclui criador, sala, método, tipo e um ID de mensagem diferente de zero. IDs ausentes não permitem identificar repetições. A contabilização de combos de presentes usa identidade de remetente/presente/grupo e máximos cumulativos, para que um pacote final não atribua a mesma quantidade duas vezes. Preços desconhecidos permanecem zero. Transições de agregados podem apoiar o cruzamento de um limite com <code>previous &lt; threshold &lt;= total</code>; não substituem os originais públicos.</p><h2 id="implement-a-consumer" tabindex="-1">Implemente um consumidor <a class="header-anchor" href="#implement-a-consumer" aria-label="Permalink to “Implemente um consumidor”">​</a></h2><ol><li>Use tipos de <code>src/automation/contracts/generated/</code> ou o analisador de envelope de domínio de widgets para esse limite.</li><li>Preserve cursores de entrega durante a serialização e elimine sobreposição ao combinar tempo real e histórico.</li><li>Processe lotes ordenados sem emitir uma renderização reativa por evento.</li><li>Exponha sinais explícitos de lacuna/sobrecarga. Recupere a apresentação com páginas limitadas ou um instantâneo novo, nunca invocando pontos ou ações novamente.</li></ol><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automation</span></span></code></pre></div><p>A <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-core/src/contracts" target="_blank" rel="noreferrer">fonte dos contratos Rust</a> gera o registro de eventos, esquemas e amostras; não reproduza tabelas completas de campos de eventos manualmente.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>A sobreposição de reconexão só é deduplicada enquanto o evento identificado permanecer no armazenamento finito atual. Filas, contadores, histórico e caches de repetição permanecem limitados. Isso não é um arquivo ilimitado de eventos nem uma garantia universal de execução exatamente uma vez. Esgotamento de capacidade e persistência indisponível têm consequências explícitas para a integridade.</p><h2 id="recover-and-verify" tabindex="-1">Recupere e verifique <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to “Recupere e verifique”">​</a></h2><p>Use dados sanitizados de presentes/emotes e teste pacotes finais de combo, IDs ausentes, identidade entre salas e lacunas de reconexão. Inspecione a revisão atual do assinador em <code>Cargo.toml</code> em vez de copiar um hash de um relatório antigo de confiabilidade. Métodos desconhecidos do serviço continuam desconhecidos até que a normalização e os contratos gerados os adicionem deliberadamente.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes de operação”">​</a></h2><p>Os padrões atuais (2026-11-13) são limites de implementação, não SLA. A entrada LIVE comporta 2.048 itens e a fila de efeitos 128, não orçamentos de bytes. Eventos de ciclo de vida aguardam capacidade. Presentes/follows/shares aguardam até um segundo antes do descarte com lacuna; chat/likes/joins/outros dados são descartados imediatamente na saturação. Confira <code>droppedCritical</code>, lotes/unidades de likes e perdas de efeitos: uma entrada descartada pode nunca ter executado efeitos. Backfill recupera apenas apresentação, nunca pontos ou ações.</p><p>A deduplicação guarda até 4.096 identidades por 300 segundos em memória do processo, entre reconexões enquanto o armazenamento existir. Expiração, expulsão por capacidade, IDs ausentes ou reinício removem a proteção. A proteção contra sobreposição vale somente nesses limites.</p><p><code>ui.feed.backfill</code> recebe <code>{version:1,after:0,limit:64}</code>, cursor numérico global e limite 1–512. Confira <code>oldestCursor</code>, <code>latestCursor</code>, <code>gap</code> e <code>truncated</code>; continue do último cursor recebido. Para uma consulta rápida por agente sem novo RPC, <code>tiktools api event get &lt;name&gt; [--type kind]... [--author text] [--limit N]</code> percorre esse diário no cliente e retorna as correspondências mais recentes; o nome é uma substring insensível a maiúsculas/minúsculas de qualquer campo de texto, e <code>--type</code> aceita <code>chat</code>/<code>gift</code>/<code>like</code>/<code>member</code>/<code>social</code> além de <code>join</code>/<code>follow</code>. <code>ui.feed.creator</code> usa <code>{creatorId,streamId,after,limit}</code>, cursores textuais por stream/criador, limite 1–64 e orçamento de bytes. Não misture os cursores. Se o stream mudar/for expulso, o cursor estiver no futuro, houver lacuna ou <code>CreatorFeedUnavailable</code>, atualize a apresentação autoritativa e sinalize histórico incompleto, sem reconstruir efeitos.</p><p>TikTok inicializa sessão, sala, catálogo de presentes, bundle de assinatura e socket. Configuração: <code>TIKTOOLS_TIKTOK_SIGNING_BUNDLE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_CACHE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_URL</code>. Padrões: cinco tentativas, espera inicial 2 s até 30 s. HTTP 429 usa Retry-After ou mínimo crescente 30–300 s com jitter, até duas novas tentativas por rate limit, mantendo cooldown após cancelar/esgotar. Outros casos exigem falha transitória de transporte. Inspecione <code>Reconnecting { attempt, delay_ms }</code> e a etapa; não inclua cookies ou material privado de assinatura.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system.health</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div>`,20)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};